head.b:skin:
:root {
    --bg: #05070a;
    --card: #0f172a;
    --accent: #10b981;
    --gold: #eab308;
    --text: #f8fafc;
    --border: rgba(16, 185, 129, 0.1);
}

body { 
    background: var(--bg); 
    color: var(--text); 
    font-family: 'Plus Jakarta Sans', sans-serif; 
    margin: 0; padding: 20px;
    min-height: 100vh;
}

.container { max-width: 1200px; margin: 0 auto; transition: 0.5s cubic-bezier(0.4, 0, 0.2, 1); }

.zen-active .config-panel { display: none; }
.zen-active .main-grid { grid-template-columns: 1fr; }
.zen-active .container { max-width: 800px; }

header { 
    display: flex; justify-content: space-between; align-items: center;
    padding-bottom: 20px; border-bottom: 1px solid var(--border); margin-bottom: 30px;
}

.brand h1 { font-size: 1.4rem; font-weight: 800; letter-spacing: -0.5px; margin: 0; }
.brand h1 span { color: var(--accent); }

.main-grid { display: grid; grid-template-columns: 350px 1fr; gap: 30px; }

.config-panel { 
    background: var(--card); border-radius: 20px; padding: 30px;
    border: 1px solid var(--border); height: fit-content;
    position: sticky; top: 20px;
}

label { 
    display: block; font-size: 0.65rem; font-weight: 800; color: #64748b;
    text-transform: uppercase; letter-spacing: 1.5px; margin: 15px 0 8px 0;
}

select {
    width: 100%; background: #020617; border: 1px solid #1e293b;
    color: white; padding: 12px; border-radius: 10px; font-size: 0.9rem;
}

.btn-primary {
    width: 100%; background: var(--accent); color: #020617;
    border: none; padding: 15px; border-radius: 10px; font-weight: 800;
    cursor: pointer; margin-top: 20px; text-transform: uppercase;
}

.btn-zen {
    background: transparent; border: 1px solid var(--accent);
    color: var(--accent); padding: 8px 15px; border-radius: 20px;
    font-size: 0.7rem; font-weight: 800; cursor: pointer;
}

.quran-card {
    background: #020617; border-radius: 24px; padding: 40px;
    border: 1px solid var(--border); animation: fadeIn 0.5s ease;
}

.arabic-text {
    font-family: 'Amiri', serif; font-size: 2.2rem; text-align: right;
    direction: rtl; line-height: 2; color: var(--gold); margin-bottom: 20px;
}

.translation { font-size: 1.1rem; line-height: 1.6; color: #94a3b8; }

/* PROMPT BOX & COPY BUTTON */
.prompt-wrapper { position: relative; margin-top: 25px; }

pre {
    background: #000; color: #10b981; padding: 25px; border-radius: 12px;
    font-size: 0.85rem; overflow-x: auto; border: 1px solid #1e293b;
    font-family: 'Courier New', monospace;
}

.copy-btn {
    position: absolute; top: 12px; right: 12px;
    background: var(--accent); color: #000; border: none;
    padding: 6px 12px; border-radius: 6px; font-size: 0.7rem;
    font-weight: 800; cursor: pointer; transition: 0.2s;
    display: flex; align-items: center; gap: 5px;
}

.copy-btn:hover { opacity: 0.9; transform: scale(1.05); }
.copy-btn.copied { background: var(--gold); }

@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

body.script:
//
const quranList = [
    {id: 1, name: "Al-Fatihah", total: 7},
    {id: 18, name: "Al-Kahf", total: 110},
    {id: 36, name: "Ya-Sin", total: 83},
    {id: 55, name: "Ar-Rahman", total: 78},
    {id: 56, name: "Al-Waqi'ah", total: 96},
    {id: 67, name: "Al-Mulk", total: 30}
];

function initApp() {
    const select = document.getElementById('surahSelect');
    select.innerHTML = '<option value="">-- Pilih Surah --</option>';
    quranList.forEach(s => {
        let opt = document.createElement('option');
        opt.value = s.id;
        opt.textContent = `${s.id}. ${s.name}`;
        select.appendChild(opt);
    });
}

function onSurahChange() {
    const id = document.getElementById('surahSelect').value;
    const ayatSelect = document.getElementById('ayatSelect');
    const surah = quranList.find(s => s.id == id);
    ayatSelect.innerHTML = '<option value="all">Semua Ayat</option>';
    if(surah) {
        for(let i=1; i<=surah.total; i++) {
            let opt = document.createElement('option');
            opt.value = i;
            opt.textContent = `Ayat ${i}`;
            ayatSelect.appendChild(opt);
        }
    }
}

function toggleZen() {
    document.getElementById('appBody').classList.toggle('zen-active');
}

function resetAll() {
    document.getElementById('surahSelect').selectedIndex = 0;
    document.getElementById('ayatSelect').innerHTML = '<option value="all">Semua Ayat</option>';
    document.getElementById('outputContainer').innerHTML = '<div style="text-align:center; padding-top:200px; color:#1e293b; font-weight:800; letter-spacing:10px;">READY FOR ENGINE</div>';
}

async function copyPrompt(btn) {
    const pre = btn.nextElementSibling;
    try {
        await navigator.clipboard.writeText(pre.textContent);
        btn.innerHTML = '<i class="fas fa-check"></i> COPIED';
        btn.classList.add('copied');
        setTimeout(() => {
            btn.innerHTML = '<i class="fas fa-copy"></i> COPY JSON';
            btn.classList.remove('copied');
        }, 2000);
    } catch (err) {
        console.error('Gagal menyalin: ', err);
    }
}

async function generateViz() {
    const sId = document.getElementById('surahSelect').value;
    if(!sId) return;

    const out = document.getElementById('outputContainer');
    out.innerHTML = '<div style="text-align:center; padding:50px;">PROCESSING ENGINE...</div>';

    try {
        const response = await fetch(`https://equran.id/api/v2/surat/${sId}`);
        const json = await response.json();
        const data = json.data;
        const aId = document.getElementById('ayatSelect').value;
        const style = document.getElementById('styleSelect').value;

        let contentHtml = '';
        let promptData = "";

        if(aId === 'all') {
            data.ayat.slice(0, 1).forEach(a => { 
                contentHtml += `<div class="arabic-text">${a.teksArab}</div><div class="translation">${a.nomorAyat}. ${a.teksIndonesia}</div>`;
            });
            promptData = `Full Surah ${data.namaLatin}`;
        } else {
            const a = data.ayat.find(item => item.nomorAyat == aId);
            contentHtml = `<div class="arabic-text">${a.teksArab}</div><div class="translation">${a.nomorAyat}. ${a.teksIndonesia}</div>`;
            promptData = `Ayat ${aId} of Surah ${data.namaLatin}`;
        }

        const promptObj = {
            handle: "@holy",
            project: "QuranViz_v2",
            config: {
                metadata: { surah: data.namaLatin, target: promptData },
                aesthetic: style,
                ratio: "9:16",
                prompt: `Masterpiece Islamic Infographic, ${style} style, ${promptData}, cinematic lighting, premium typography, 8k resolution --ar 9:16`
            }
        };

        out.innerHTML = `
            <div class="quran-card">
                <div style="font-size:0.7rem; color:var(--accent); font-weight:800; margin-bottom:10px; letter-spacing:2px;">FORGING CONTENT...</div>
                ${contentHtml}
                <div class="prompt-wrapper">
                    <button class="copy-btn" onclick="copyPrompt(this)">
                        <i class="fas fa-copy"></i> COPY JSON
                    </button>
                    <pre>${JSON.stringify(promptObj, null, 4)}</pre>
                </div>
            </div>
        `;

    } catch (e) {
        out.innerHTML = "Error loading engine.";
    }
}

window.onload = initApp;
//
